WITH valid_departments AS (SELECT * FROM departments WHERE location = 'New York'), DepartmentsStats AS (SELECT location, CASE WHEN budget >= 3770000 THEN 'high' WHEN budget >= 1053000 THEN 'mid' ELSE 'low' END AS budget_bucket, MAX(budget) AS max_budget FROM valid_departments GROUP BY location, CASE WHEN budget >= 3770000 THEN 'high' WHEN budget >= 1053000 THEN 'mid' ELSE 'low' END) SELECT * FROM DepartmentsStats WHERE max_budget > 1365000 ORDER BY budget_bucket, max_budget;
